import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { cloudflare, type CloudflareBindings } from "@/lib/cloudflare";

/**
 * Where image files live. Development uses the local disk (./.media, git-ignored).
 * Production uses a Cloudflare R2 bucket bound to the Worker as MEDIA_BUCKET.
 */
export interface MediaStorage {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<{ bytes: Uint8Array; contentType: string } | null>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server only; this pattern rejects anything else (no path traversal). */
export const MEDIA_KEY_PATTERN = /^media\/\d{4}\/\d{2}\/[0-9a-f-]{36}-\d{2,4}\.webp$/;
/** Frames of a scroll film: seq/<uuid>/d|m/NNNN.webp */
export const SEQUENCE_KEY_PATTERN = /^seq\/[0-9a-f-]{36}\/[dm]\/\d{4}\.webp$/;
export const isStorageKey = (key: string) => MEDIA_KEY_PATTERN.test(key) || SEQUENCE_KEY_PATTERN.test(key);

class LocalDiskStorage implements MediaStorage {
  constructor(private readonly root: string) {}

  private resolve(key: string) {
    if (!isStorageKey(key)) throw new Error("Invalid media key");
    return path.join(this.root, key);
  }

  async put(key: string, bytes: Uint8Array) {
    const file = this.resolve(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, bytes);
  }

  async get(key: string) {
    try {
      return { bytes: new Uint8Array(await readFile(this.resolve(key))), contentType: "image/webp" };
    } catch {
      return null;
    }
  }

  async delete(key: string) {
    await rm(this.resolve(key), { force: true });
  }
}

/** R2 bucket through the Worker binding (no keys needed, never public by itself). */
class R2Storage implements MediaStorage {
  constructor(private readonly bucket: NonNullable<CloudflareBindings["MEDIA_BUCKET"]>) {}

  async put(key: string, bytes: Uint8Array, contentType: string) {
    if (!isStorageKey(key)) throw new Error("Invalid media key");
    await this.bucket.put(key, bytes, { httpMetadata: { contentType, cacheControl: "public, max-age=31536000, immutable" } });
  }

  async get(key: string) {
    if (!isStorageKey(key)) return null;
    const obj = await this.bucket.get(key);
    if (!obj) return null;
    return { bytes: new Uint8Array(await obj.arrayBuffer()), contentType: obj.httpMetadata?.contentType ?? "image/webp" };
  }

  async delete(key: string) {
    if (isStorageKey(key)) await this.bucket.delete(key);
  }
}

/** Vercel Blob (test environment on Vercel). Private store: files are only served through /media. */
class VercelBlobStorage implements MediaStorage {
  async put(key: string, bytes: Uint8Array, contentType: string) {
    if (!isStorageKey(key)) throw new Error("Invalid media key");
    const { put } = await import("@vercel/blob");
    await put(key, Buffer.from(bytes), { access: "private", contentType, addRandomSuffix: false, cacheControlMaxAge: 31_536_000 });
  }

  async get(key: string) {
    if (!isStorageKey(key)) return null;
    const { get } = await import("@vercel/blob");
    const r = await get(key, { access: "private" });
    if (!r?.stream) return null;
    return { bytes: new Uint8Array(await new Response(r.stream).arrayBuffer()), contentType: r.blob.contentType ?? "image/webp" };
  }

  async delete(key: string) {
    if (!isStorageKey(key)) return;
    const { del } = await import("@vercel/blob");
    await del(key);
  }
}

let storage: MediaStorage | null = null;

export function getMediaStorage(): MediaStorage {
  const bucket = cloudflare()?.env.MEDIA_BUCKET;
  if (bucket) return new R2Storage(bucket);
  if (storage) return storage;
  if (process.env.BLOB_READ_WRITE_TOKEN) {
    storage = new VercelBlobStorage();
    return storage;
  }
  const driver = process.env.MEDIA_DRIVER ?? "local";
  if (driver === "local") {
    storage = new LocalDiskStorage(path.resolve(/*turbopackIgnore: true*/ process.cwd(), process.env.MEDIA_LOCAL_DIR ?? ".media"));
    return storage;
  }
  throw new Error(`Media driver "${driver}" needs the MEDIA_BUCKET binding (Cloudflare R2).`);
}

/** Public URL of a stored file. */
export function mediaUrl(key: string): string {
  const base = process.env.NEXT_PUBLIC_MEDIA_BASE_URL ?? "";
  return `${base}/${key}`;
}
